import assert from 'node:assert/strict';import { performance } from 'node:perf_hooks';import {prepareDataGrid,gridVirtualWindow} from '../core/data_grid_engine.mjs';
const rows=[{id:1,v:0,name:'Zero'},{id:2,v:null,name:'Missing'},{id:3,v:5,name:'Five'},{id:4,v:2,name:'Two'}];const model=prepareDataGrid({rows,columns:[{key:'id',type:'number'},{key:'v',type:'number'},{key:'name',type:'text'}],sort:{key:'v',direction:'asc'}});assert.deepEqual(model.rows.map(r=>r.v),[0,2,5,null]);const desc=prepareDataGrid({rows,columns:[{key:'v',type:'number'}],sort:{key:'v',direction:'desc'}});assert.deepEqual(desc.rows.map(r=>r.v),[5,2,0,null]);
const big=Array.from({length:100000},(_,i)=>({id:i+1,tool:['ETCH','CVD','CMP'][i%3],v:i%101===0?null:(i%1000)/10}));const t0=performance.now();const m=prepareDataGrid({rows:big,columns:[{key:'id',type:'number'},{key:'tool',type:'text'},{key:'v',type:'number'}],sort:{key:'id',direction:'asc'}});const build=performance.now()-t0;let maxCount=0;const t1=performance.now();for(let i=0;i<10000;i++){const w=gridVirtualWindow(m.rowCount,(i*7919)%3_600_000,520,36,8);assert.ok(w.start<=w.end&&w.end<=100000);maxCount=Math.max(maxCount,w.count)}const vt=performance.now()-t1;assert.ok(maxCount<60);console.log(JSON.stringify({pass:true,zeroVsMissing:true,missingLastAscDesc:true,rows:100000,buildMs:+build.toFixed(2),virtual10kMs:+vt.toFixed(2),maxVisibleWindow:maxCount},null,2));
